contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint fund) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= fund);

        c.sendMoney(address(this), fund); if (__ESBMC_reverted()) return;

        uint beforeBalanceC = address(c).balance;
        uint beforeBalanceSelf = address(this).balance;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint afterBalanceC = address(c).balance;
        uint afterBalanceSelf = address(this).balance;

        assert(afterBalanceC == 0 && afterBalanceSelf == beforeBalanceSelf + beforeBalanceC);
    }
}

