// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 fund) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= fund);
        try c.sendMoney(address(this), fund) {} catch { return; }
        uint beforeBalanceC = address(c).balance;
        uint beforeBalanceSelf = address(this).balance;
        try c.withdrawAll() {} catch { return; }
        uint afterBalanceC = address(c).balance;
        uint afterBalanceSelf = address(this).balance;
        assertTrue(afterBalanceC == 0 && afterBalanceSelf == beforeBalanceSelf + beforeBalanceC);
    }

    function testFuzz_run(uint256 fund) public {
        _run(fund);
    }

    receive() external payable {}
}
